import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Ban IP","description":"","frontmatter":{},"headers":[],"relativePath":"security/ban-ip.md","filePath":"security/ban-ip.md"}'),n={name:"security/ban-ip.md"};function o(d,e,s,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ban-ip" tabindex="-1">Ban IP <a class="header-anchor" href="#ban-ip" aria-label="Permalink to &quot;Ban IP&quot;">​</a></h1><h3 id="request-enforcement" tabindex="-1">Request Enforcement <a class="header-anchor" href="#request-enforcement" aria-label="Permalink to &quot;Request Enforcement&quot;">​</a></h3><p>Tradeboard checks active IP bans before Flask processes a request. A banned address receives HTTP 403. Ban state is stored in <code>logs.db</code> and cached briefly; manual and automatic changes invalidate the affected cache entry.</p><p>Open <strong>Logs &gt; Security</strong> or visit <code>/logs/security</code> after signing in.</p><h3 id="stored-trackers" tabindex="-1">Stored Trackers <a class="header-anchor" href="#stored-trackers" aria-label="Permalink to &quot;Stored Trackers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ip_bans</code></td><td>Temporary or permanent bans, reason, count, creator, and expiry</td></tr><tr><td><code>error_404_tracker</code></td><td>Per-IP 404 count and up to 50 distinct attempted paths in a 24-hour window</td></tr><tr><td><code>invalid_api_key_tracker</code></td><td>Per-IP invalid-key count and up to 20 key hashes in a 24-hour window</td></tr></tbody></table><p>Raw API keys are not stored by the invalid-key tracker.</p><h3 id="automatic-ban-defaults" tabindex="-1">Automatic Ban Defaults <a class="header-anchor" href="#automatic-ban-defaults" aria-label="Permalink to &quot;Automatic Ban Defaults&quot;">​</a></h3><p>Automatic banning is <strong>off</strong> by default. The persisted settings start at:</p><table tabindex="0"><thead><tr><th>Setting</th><th style="text-align:right;">Default</th></tr></thead><tbody><tr><td>404 threshold</td><td style="text-align:right;">100 per 24 hours</td></tr><tr><td>404 ban duration</td><td style="text-align:right;">0 hours (permanent)</td></tr><tr><td>Invalid-key threshold</td><td style="text-align:right;">100 per 24 hours</td></tr><tr><td>Invalid-key ban duration</td><td style="text-align:right;">0 hours (permanent)</td></tr><tr><td>Repeat-offender limit</td><td style="text-align:right;">2 bans</td></tr></tbody></table><p>A zero-hour duration means permanent. When automatic banning is enabled, localhost addresses are excluded. Reaching the repeat-offender limit makes the next active ban permanent; durations are not automatically doubled.</p><h3 id="dashboard-actions" tabindex="-1">Dashboard Actions <a class="header-anchor" href="#dashboard-actions" aria-label="Permalink to &quot;Dashboard Actions&quot;">​</a></h3><p>The authenticated dashboard can:</p><ul><li>ban one validated IPv4 or IPv6 address;</li><li>unban an address;</li><li>resolve a host observed in recent traffic and ban matching addresses;</li><li>clear an address&#39;s 404 tracker;</li><li>inspect invalid-key and 404 activity;</li><li>update thresholds, durations, repeat limits, and the automatic-ban switch;</li><li>review login activity and active application sessions.</li></ul><p>Use a specific, factual ban reason. Host banning resolves addresses from recent stored traffic; it is not a permanent domain firewall rule and DNS can change.</p><h3 id="client-ip-resolution" tabindex="-1">Client IP Resolution <a class="header-anchor" href="#client-ip-resolution" aria-label="Permalink to &quot;Client IP Resolution&quot;">​</a></h3><p>With <code>TRUST_PROXY_HEADERS=False</code> (the default), Tradeboard uses the immediate peer address. With the setting enabled, it can accept <code>CF-Connecting-IP</code>, <code>True-Client-IP</code>, <code>X-Real-IP</code>, the first <code>X-Forwarded-For</code> value, and <code>X-Client-IP</code> in priority order.</p><p>Only enable forwarded headers when a controlled reverse proxy is the only network path to the application. Otherwise a client can spoof the address used for tracking and bans.</p><h3 id="what-ip-bans-do-not-provide" tabindex="-1">What IP Bans Do Not Provide <a class="header-anchor" href="#what-ip-bans-do-not-provide" aria-label="Permalink to &quot;What IP Bans Do Not Provide&quot;">​</a></h3><ul><li>There is no current CIDR allowlist or trusted-IP bypass feature.</li><li>Application bans do not replace a host firewall, cloud security group, VPN, WAF, or reverse-proxy policy.</li><li>A ban does not revoke a compromised broker token, API key, session, or MCP token. Revoke those credentials separately.</li><li>IP bans are not a substitute for rate limits or denial-of-service protection upstream.</li></ul><h3 id="incident-workflow" tabindex="-1">Incident Workflow <a class="header-anchor" href="#incident-workflow" aria-label="Permalink to &quot;Incident Workflow&quot;">​</a></h3><ol><li>Confirm the address and attempted paths in Security and Traffic views.</li><li>Apply a manual ban when immediate containment is justified.</li><li>Regenerate exposed API keys and reconnect or revoke broker access as required.</li><li>Revoke application sessions or MCP token families when those credentials may be affected.</li><li>Preserve relevant logs before retention purges them.</li><li>Adjust automatic thresholds only after checking for legitimate traffic patterns.</li></ol>',22)])])}const b=t(n,[["render",o]]);export{p as __pageData,b as default};
